package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;

/** Actual bundled ARM64 wimlib, original fixture files only, no OS or USB media. */
public final class WimTest {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static final class Local implements WimFiles.RandomFile {final RandomAccessFile file;Local(File path)throws IOException{file=new RandomAccessFile(path,"rw");}public long size()throws IOException{return file.length();}public int read(long at,byte[] b)throws IOException{file.seek(at);int n=0;while(n<b.length){int r=file.read(b,n,b.length-n);if(r<0)break;n+=r;}return n;}public void write(long at,byte[] b)throws IOException{file.seek(at);file.write(b);}public void truncate(long n)throws IOException{file.setLength(n);}public void sync()throws IOException{file.getFD().sync();}public void close()throws IOException{file.close();}}
 static OpticalImage.Source source(File path)throws IOException {RandomAccessFile in=new RandomAccessFile(path,"r");return new OpticalImage.Source(){public long size()throws IOException{return in.length();}public void read(long at,byte[] b,int off,int n)throws IOException{in.seek(at);in.readFully(b,off,n);}public void close()throws IOException{in.close();}};}
 static void command(File libs,String... args)throws Exception {List<String> cmd=new ArrayList<>();cmd.add(new File(libs,"libwimlib_imagex.so").getAbsolutePath());cmd.addAll(Arrays.asList(args));ProcessBuilder pb=new ProcessBuilder(cmd).redirectErrorStream(true);pb.environment().remove("LD_PRELOAD");pb.environment().remove("LD_LIBRARY_PATH");Process p=pb.start();ByteArrayOutputStream log=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=p.getInputStream().read(b))!=-1)if(log.size()<65536)log.write(b,0,n);if(p.waitFor()!=0)throw new IOException(log.toString("UTF-8"));}
 public static void main(String[] args)throws Exception {
  File libs=new File("app/src/main/jniLibs/arm64-v8a");Path temp=Files.createTempDirectory("usbwb-wim-");
  try {File input=temp.resolve("input").toFile(),output=temp.resolve("parts").toFile();check(input.mkdir()&&output.mkdir(),"fixture dirs");Random random=new Random(723);for(int i=0;i<5;i++){byte[] b=new byte[700000];random.nextBytes(b);Files.write(new File(input,"fixture"+i+".bin").toPath(),b);}Files.write(new File(input,"ملف.txt").toPath(),"USB فقط".getBytes("UTF-8"));
   File wim=temp.resolve("fixture.wim").toFile();command(libs,"capture",input.getAbsolutePath(),wim.getAbsolutePath(),"--compress=LZX","--threads=1","--check","--quiet");check(wim.length()>3000000,"real WIM fixture");
   try(WimFiles files=new WimFiles(source(wim),new WimFiles.Store(){public WimFiles.RandomFile create(String name)throws IOException{File f=new File(output,name);if(!f.createNewFile())throw new IOException("FILE_EXISTS");return new Local(f);}public void capacity(long n){}})){
    FileProtocol.Handle read=files.open("source.wim",0);byte[] magic=new byte[8];check(files.read(read.id,0,magic)==8&&magic[0]=='M',"read-only source");try{files.open("source.wim",2);throw new AssertionError("source writable");}catch(FileProtocol.FileError e){check(e.errno==30,"source write blocked");}files.close(read.id);
    WimProcess.split(libs,files,(a,b)->{},()->false,1);check(files.names().size()>=3,"multipart split "+files.names());for(String name:files.names())check(new File(output,name).length()<0xffffffffL,"FAT32 bound");
    try{files.open("install.swm",2);throw new AssertionError("sealed outputs writable");}catch(FileProtocol.FileError e){check(e.errno==30,"verify is read only");}
   }
   String first=new File(output,"install.swm").getAbsolutePath();List<String> verify=new ArrayList<>(Arrays.asList("verify",first,"--quiet"));for(File f:Objects.requireNonNull(output.listFiles()))if(!f.getName().equals("install.swm"))verify.add("--ref="+f.getAbsolutePath());command(libs,verify.toArray(new String[0]));check(true,"independent non-RPC verification");
   File exported=new File(temp.toFile(),"exported.bin");try(WimFiles files=new WimFiles(source(wim),new WimFiles.Store(){public WimFiles.RandomFile create(String name)throws IOException{if(!name.equals("export.bin"))throw new IOException("UNEXPECTED_OUTPUT");return new Local(exported);}public void capacity(long n){}})){
    String listing=WimProcess.run(libs,Arrays.asList("dir","/usbwb/source.wim","1"),files,(a,b)->{},()->false);check(listing.contains("fixture0.bin")&&listing.contains("ملف.txt"),"real WIM directory list");
    WimProcess.run(libs,Arrays.asList("extract","/usbwb/source.wim","1","/fixture0.bin","--to-stdout","--no-globs","--quiet"),files,(a,b)->{},()->false,true);files.seal();check(Arrays.equals(Files.readAllBytes(new File(input,"fixture0.bin").toPath()),Files.readAllBytes(exported.toPath())),"single-file binary export through bounded stdout RPC");
   }
   File restored=temp.resolve("restored").toFile();List<String> apply=new ArrayList<>(Arrays.asList("apply",first,"1",restored.getAbsolutePath(),"--quiet"));for(File f:Objects.requireNonNull(output.listFiles()))if(!f.getName().equals("install.swm"))apply.add("--ref="+f.getAbsolutePath());command(libs,apply.toArray(new String[0]));for(File original:Objects.requireNonNull(input.listFiles()))check(Arrays.equals(Files.readAllBytes(original.toPath()),Files.readAllBytes(new File(restored,original.getName()).toPath())),"roundtrip "+original.getName());
   System.out.println("PASS: "+checks+" actual WIM capture, bounded streaming split, read-only verification and extraction roundtrip checks");
  }finally{try(java.util.stream.Stream<Path> paths=Files.walk(temp)){paths.sorted(Comparator.reverseOrder()).forEach(path->{try{Files.delete(path);}catch(IOException ignored){}});}}
 }
}
